// The Progen Labs mark: the Seed, a ribbon of light that grows from a point,
// turns about its spine and closes to a point. The SVGs are generated by
// scripts/brand.mjs into public/brand/ — the same files the READMEs show —
// and animate by themselves (SMIL), so this is just an image: the turning
// mark normally, a still one when the visitor prefers reduced motion.
import { useReducedMotion } from 'framer-motion';

const BRAND = `${import.meta.env.BASE_URL}brand/`;

export default function ProgenMark({ theme = 'dark', className = '' }) {
  const still = useReducedMotion();
  const file = `progen-seed-mark${theme === 'light' ? '-light' : ''}${still ? '-still' : ''}.svg`;
  return <img className={`pl-mark ${className}`.trim()} data-theme={theme} src={`${BRAND}${file}`} alt="" aria-hidden="true" width="66" height="94" decoding="async" />;
}
